() => {
  const cards = document.querySelectorAll('a[id*="mntl-card-list-card"]');
  const results = [];
  cards.forEach(card => {
    const titleEl = card.querySelector('span.card__title');
    const ratingEl = card.querySelector('.mntl-recipe-card-meta__rating');
    const countEl = card.querySelector('.mntl-recipe-card-meta__rating-count-number');
    const url = card.href;
    if (titleEl) {
      results.push({
        title: titleEl.textContent.trim(),
        rating: ratingEl ? ratingEl.getAttribute('aria-label') || ratingEl.textContent.trim() : null,
        ratingCount: countEl ? countEl.textContent.trim() : null,
        url: url
      });
    }
  });
  return results;
}

() => {
  const cards = document.querySelectorAll('a[id*="mntl-card-list-card"]');
  const results = [];
  cards.forEach(card => {
    const titleEl = card.querySelector('span.card__title');
    const ratingEl = card.querySelector('[id*="mntl-recipe-star-rating"]');
    const countEl = card.querySelector('[id*="mntl-recipe-card-meta"] .mntl-recipe-card-meta__rating-count-number, [id*="mntl-recipe-card-meta"] div');
    const url = card.href;
    const title = titleEl ? titleEl.textContent.trim() : null;
    if (title) {
      results.push({
        title: title,
        ratingText: ratingEl ? ratingEl.textContent.trim() : 'no rating',
        ratingHTML: ratingEl ? ratingEl.outerHTML.substring(0, 300) : null,
        countText: countEl ? countEl.textContent.trim() : 'no count',
        url: url
      });
    }
  });
  return JSON.stringify(results);
}

() => {
  const cards = document.querySelectorAll('a[id*="mntl-card-list-card"]');
  const results = [];
  cards.forEach((card, i) => {
    if (i > 20) return;
    const allSpans = Array.from(card.querySelectorAll('span')).map(s => s.textContent.trim()).filter(t => t);
    const allDivs = Array.from(card.querySelectorAll('div')).map(d => d.textContent.trim()).filter(t => t && t.length < 100);
    const titleEl = card.querySelector('.card__title');
    results.push({
      title: titleEl ? titleEl.textContent.trim() : 'NO TITLE',
      titleAttr: card.getAttribute('aria-label'),
      href: card.href,
      innerText: card.innerText.substring(0, 500)
    });
  });
  return results;
}

() => {
  const result = [];
  const cards = document.querySelectorAll('a[id*="mntl-card-list-card"]');
  for (const card of cards) {
    const titleEl = card.querySelector('.card__title, span.card__title');
    const title = titleEl ? titleEl.textContent.trim() : (card.getAttribute('aria-label') || 'unknown');
    const url = card.getAttribute('href');
    // Find rating in card
    const starsEl = card.querySelector('[id*="mntl-recipe-star-rating"]');
    const ratingText = starsEl ? starsEl.textContent.trim() : '';
    // Find rating count
    const metaDivs = card.querySelectorAll('[id*="mntl-recipe-card-meta"] > div');
    const counts = [];
    metaDivs.forEach(d => counts.push(d.textContent.trim()));
    result.push({title, url, ratingText, counts});
  }
  return result;
}

() => {
  const ratingEl = document.querySelector('#mm-recipes-review-bar__rating_1-0');
  const reviewsEl = document.querySelector('#mm-recipes-review-bar__comment-count_1-0');
  const prepTimeEls = document.querySelectorAll('.mntl-recipe-details__value');
  const ingredients = Array.from(document.querySelectorAll('.mntl-structured-ingredients__list-item')).map(li => li.textContent.trim());
  return {
    rating: ratingEl ? ratingEl.textContent.trim() : 'none',
    reviews: reviewsEl ? reviewsEl.textContent.trim() : 'none',
    prepDetails: Array.from(prepTimeEls).map(e => e.textContent.trim()),
    ingredients: ingredients
  };
}
